import{_ as t,a0 as p,w as o,s as d,ao as c,I as l,x as e,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"一套有用的 Unix 实用程序 | LCTT x X-CMD","titleTemplate":false,"description":"一套有用的 Unix 实用程序 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一套有用的 Unix 实用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一套有用的 Unix 实用程序 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180821 A Collection Of More Useful Unix Utilities","title":"一套有用的 Unix 实用程序","tag":"201808","desc":""},"relativePath":"201808/20180821 A Collection Of More Useful Unix Utilities.md","filePath":"[post].md"}'),r={name:"201808/20180821 A Collection Of More Useful Unix Utilities.md"};function h(g,s,k,u,b,f){const i=p("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="一套有用的-unix-实用程序" tabindex="-1">一套有用的 Unix 实用程序 <a class="header-anchor" href="#一套有用的-unix-实用程序" aria-label="Permalink to “一套有用的 Unix 实用程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/08/Moreutils-720x340.png" alt=""></p><p>我们都了解 <ruby>GNU 核心实用程序<rt>GNU Core Utilities</rt></ruby>，所有类 Unix 操作系统都预装了它们。它们是 GNU 操作系统中与文件、Shell 和 文本处理相关的基础实用工具。GNU 核心实用程序包括很多日常操作命令，例如 <code>cat</code>、<code>ls</code>、<code>rm</code>、<code>mkdir</code>、<code>rmdir</code>、<code>touch</code>、<code>tail</code> 和 <code>wc</code> 等。除了这些实用程序，还有更多有用的实用程序没有预装在类 Unix 操作系统中，它们汇集起来构成了 <code>moreutilis</code> 这个日益增长的集合。<code>moreutils</code> 可以在 GNU/Linux 和包括 FreeBSD，openBSD 及 Mac OS 在内的多种 Unix 类型操作系统上安装。</p><p>截至到编写这份指南时， <code>moreutils</code> 提供如下实用程序：</p><ul><li><code>chronic</code> – 运行程序并忽略正常运行的输出</li><li><code>combine</code> – 使用布尔操作合并文件的行</li><li><code>errno</code> – 查询 errno 名称及描述</li><li><code>ifdata</code> – 获取网络接口信息，无需解析 <code>ifconfig</code> 的结果</li><li><code>ifne</code> – 在标准输入非空的情况下运行程序</li><li><code>isutf8</code> – 检查文件或标准输入是否采用 UTF-8 编码</li><li><code>lckdo</code> – 带锁运行程序</li><li><code>mispipe</code> – 使用管道连接两个命令，返回第一个命令的退出状态</li><li><code>parallel</code> – 同时运行多个任务</li><li><code>pee</code> – 将标准输入传递给多个管道</li><li><code>sponge</code> – 整合标准输入并写入文件</li><li><code>ts</code> – 为标准输入增加时间戳信息</li><li><code>vidir</code> – 使用你默认的文本编辑器操作目录文件</li><li><code>vipe</code> – 在管道中插入信息编辑</li><li><code>zrun</code> – 自动解压并将其作为参数传递给命令</li></ul><h3 id="在-linux-上安装-moreutils" tabindex="-1">在 Linux 上安装 moreutils <a class="header-anchor" href="#在-linux-上安装-moreutils" aria-label="Permalink to “在 Linux 上安装 moreutils”">​</a></h3><p>由于 <code>moreutils</code> 已经被打包到多种 Linux 发行版中，你可以使用发行版对应的软件包管理器安装 <code>moreutils</code>。</p><p>在 <strong>Arch Linux</strong> 或衍生的 <strong>Antergos</strong> 和 <strong>Manjaro Linux</strong> 上，运行如下命令安装 <code>moreutils</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S moreutils</span></span></code></pre></div><p>在 <strong>Fedora</strong> 上，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install moreutils</span></span></code></pre></div><p>在 <strong>RHEL</strong>，<strong>CentOS</strong> 和 <strong>Scientific Linux</strong> 上，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install moreutils</span></span></code></pre></div><p>在 <strong>Debian</strong>，<strong>Ubuntu</strong> 和 <strong>Linux Mint</strong> 上，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install moreutils</span></span></code></pre></div><h3 id="moreutils-–-打包更多有用的-unix-实用程序" tabindex="-1">Moreutils – 打包更多有用的 Unix 实用程序 <a class="header-anchor" href="#moreutils-–-打包更多有用的-unix-实用程序" aria-label="Permalink to “Moreutils – 打包更多有用的 Unix 实用程序”">​</a></h3><p>让我们看一下几个 <code>moreutils</code> 工具的用法细节。</p><h4 id="combine-实用程序" tabindex="-1">combine 实用程序 <a class="header-anchor" href="#combine-实用程序" aria-label="Permalink to “combine 实用程序”">​</a></h4><p>正如 <code>combine</code> 名称所示，moreutils 中的这个实用程序可以使用包括 <code>and</code>，<code>not</code>，<code>or</code> 和 <code>xor</code> 在内的布尔操作，合并两个文件中的行。</p><ul><li><code>and</code> – 输出 <code>file1</code> 和 <code>file2</code> 都包含的行。</li><li><code>not</code> – 输出 <code>file1</code> 包含但 <code>file2</code> 不包含的行。</li><li><code>or</code> – 输出 <code>file1</code> 或 <code>file2</code> 包含的行。</li><li><code>xor</code> – 输出仅被 <code>file1</code> 或 <code>file2</code> 包含的行</li></ul><p>下面举例说明，方便你理解该实用程序的功能。这里有两个文件，文件名分别为 <code>file1</code> 和 <code>file2</code>，其内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1</span></span>
<span class="line"><span>is</span></span>
<span class="line"><span>was</span></span>
<span class="line"><span>were</span></span>
<span class="line"><span>where</span></span>
<span class="line"><span>there</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat file2</span></span>
<span class="line"><span>is</span></span>
<span class="line"><span>were</span></span>
<span class="line"><span>there</span></span></code></pre></div><p>下面，我使用 <code>and</code> 布尔操作合并这两个文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ combine file1 and file2</span></span>
<span class="line"><span>is</span></span>
<span class="line"><span>were</span></span>
<span class="line"><span>there</span></span></code></pre></div><p>从上例的输出中可以看出，<code>and</code> 布尔操作只输出那些 <code>file1</code> 和 <code>file2</code> 都包含的行；更具体的来说，命令输出为两个文件共有的行，即 is，were 和 there。</p><p>下面我们换成 <code>not</code> 操作，观察一下输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ combine file1 not file2</span></span>
<span class="line"><span>was</span></span>
<span class="line"><span>where</span></span></code></pre></div><p>从上面的输出中可以看出，<code>not</code> 操作输出 <code>file1</code> 包含但 <code>file2</code> 不包含的行。</p><h4 id="ifdata-实用程序" tabindex="-1">ifdata 实用程序 <a class="header-anchor" href="#ifdata-实用程序" aria-label="Permalink to “ifdata 实用程序”">​</a></h4><p><code>ifdata</code> 实用程序可用于检查网络接口是否存在，也可用于获取网络接口的信息，例如 IP 地址等。与预装的 <code>ifconfig</code> 和 <code>ip</code> 命令不同，<code>ifdata</code> 的输出更容易解析，这种设计的初衷是便于在 Shell 脚本中使用。</p><p>如果希望查看某个接口的 IP 地址，不妨以 <code>wlp9s0</code> 为例，运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -p wlp9s0</span></span>
<span class="line"><span>192.168.43.192 255.255.255.0 192.168.43.255 1500</span></span></code></pre></div><p>如果只查看掩码信息，运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -pn wlp9s0</span></span>
<span class="line"><span>255.255.255.0</span></span></code></pre></div><p>如果查看网络接口的物理地址，运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -ph wlp9s0</span></span>
<span class="line"><span>A0:15:46:90:12:3E</span></span></code></pre></div><p>如果判断接口是否存在，可以使用 <code>-pe</code> 参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -pe wlp9s0</span></span>
<span class="line"><span>yes</span></span></code></pre></div><h4 id="pee-命令" tabindex="-1">pee 命令 <a class="header-anchor" href="#pee-命令" aria-label="Permalink to “pee 命令”">​</a></h4><p>该命令某种程度上类似于 <code>tee</code> 命令。</p><p>我们先用一个例子看一下 <code>tee</code> 的用法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Welcome to OSTechNIx&quot; | tee file1 file2</span></span>
<span class="line"><span>Welcome to OSTechNIx</span></span></code></pre></div><p>上述命令首先创建两个文件，名为 <code>file1</code> 和 <code>file2</code>；接着，将 “Welcome to OSTechNix” 行分别附加到两个文件中；最后，在终端中打印输出 “Welcome to OSTechNix”。</p><p><code>pee</code> 命令提供类似的功能，但与 <code>tee</code> 又稍微有些差异。查看下面的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Welcome to OSTechNIx&quot; | pee cat cat</span></span>
<span class="line"><span>Welcome to OSTechNIx</span></span>
<span class="line"><span>Welcome to OSTechNIx</span></span></code></pre></div><p>从上面的命令输出中可以看出，有两个 <code>cat</code> 命令实例获取 <code>echo</code> 命令的输出并执行，因而终端中出现两个同样的输出。</p><h4 id="sponge-实用程序" tabindex="-1">sponge 实用程序 <a class="header-anchor" href="#sponge-实用程序" aria-label="Permalink to “sponge 实用程序”">​</a></h4><p>这是 <code>moreutils</code> 软件包中的另一个有用的实用程序。<code>sponge</code> 读取标准输入并写入到指定的文件中。与 Shell 中的重定向不同，<code>sponge</code> 接收到完整输入后再写入输出文件。</p><p>查看下面这个文本文件的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1</span></span>
<span class="line"><span>I</span></span>
<span class="line"><span>You</span></span>
<span class="line"><span>Me</span></span>
<span class="line"><span>We</span></span>
<span class="line"><span>Us</span></span></code></pre></div><p>可见，文件包含了一些无序的行；更具体的说，这些行“没有”按照字母顺序排序。如果希望将其内容安装字母顺序排序，你会怎么做呢？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sort file1 &gt; file1_sorted</span></span></code></pre></div><p>这样做没错，对吧？当然没错！在上面的命令中，我将 <code>file1</code> 文件内容按照字母顺序排序，将排序后的内容保存在 <code>file1_sorted</code> 文件中。但如果使用 <code>sponge</code> 命令，你可以在不创建新文件（即 <code>file1_sorted</code>）的情况下完成同样的任务，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sort file1 | sponge file1</span></span></code></pre></div><p>那么，让我们检查一下文件内容是否已经按照字母顺序排序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1</span></span>
<span class="line"><span>I</span></span>
<span class="line"><span>Me</span></span>
<span class="line"><span>Us</span></span>
<span class="line"><span>We</span></span>
<span class="line"><span>You</span></span></code></pre></div><p>看到了吧？并不需要创建新文件。在脚本编程中，这非常有用。另一个好消息是，如果待写入的文件已经存在，<code>sponge</code> 会保持其<ruby>权限信息<rt>permissions</rt></ruby>不变。</p><h4 id="ts-实用程序" tabindex="-1">ts 实用程序 <a class="header-anchor" href="#ts-实用程序" aria-label="Permalink to “ts 实用程序”">​</a></h4><p>正如名称所示，<code>ts</code> 命令在每一行输出的行首增加<ruby>时间戳<rt>timestamp</rt></ruby>。</p><p>查看如下命令的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 2 localhost</span></span>
<span class="line"><span>PING localhost(localhost.localdomain (::1)) 56 data bytes</span></span>
<span class="line"><span>64 bytes from localhost.localdomain (::1): icmp_seq=1 ttl=64 time=0.055 ms</span></span>
<span class="line"><span>64 bytes from localhost.localdomain (::1): icmp_seq=2 ttl=64 time=0.079 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- localhost ping statistics ---</span></span>
<span class="line"><span>2 packets transmitted, 2 received, 0% packet loss, time 1018ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.055/0.067/0.079/0.012 ms</span></span></code></pre></div><p>下面，结合 <code>ts</code> 实用程序运行同样地命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 2 localhost | ts</span></span>
<span class="line"><span>Aug 21 13:32:28 PING localhost(localhost (::1)) 56 data bytes</span></span>
<span class="line"><span>Aug 21 13:32:28 64 bytes from localhost (::1): icmp_seq=1 ttl=64 time=0.063 ms</span></span>
<span class="line"><span>Aug 21 13:32:28 64 bytes from localhost (::1): icmp_seq=2 ttl=64 time=0.113 ms</span></span>
<span class="line"><span>Aug 21 13:32:28</span></span>
<span class="line"><span>Aug 21 13:32:28 --- localhost ping statistics ---</span></span>
<span class="line"><span>Aug 21 13:32:28 2 packets transmitted, 2 received, 0% packet loss, time 4ms</span></span>
<span class="line"><span>Aug 21 13:32:28 rtt min/avg/max/mdev = 0.063/0.088/0.113/0.025 ms</span></span></code></pre></div><p>对比输出可以看出，<code>ts</code> 在每一行行首增加了时间戳。下面给出另一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l | ts</span></span>
<span class="line"><span>Aug 21 13:34:25 total 120</span></span>
<span class="line"><span>Aug 21 13:34:25 drwxr-xr-x 2 sk users 12288 Aug 20 20:05 Desktop</span></span>
<span class="line"><span>Aug 21 13:34:25 drwxr-xr-x 2 sk users 4096 Aug 10 18:44 Documents</span></span>
<span class="line"><span>Aug 21 13:34:25 drwxr-xr-x 24 sk users 12288 Aug 21 13:06 Downloads</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h4 id="vidir-实用程序" tabindex="-1">vidir 实用程序 <a class="header-anchor" href="#vidir-实用程序" aria-label="Permalink to “vidir 实用程序”">​</a></h4><p><code>vidir</code> 实用程序可以让你使用 <code>vi</code> 编辑器（或其它 <code>$EDITOR</code> 环境变量指定的编辑器）编辑指定目录的内容。如果没有指定目录，<code>vidir</code> 会默认编辑你当前的目录。</p><p>下面的命令编辑 <code>Desktop</code> 目录的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vidir Desktop/</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/sk@sk_001-1.png" alt="vidir"></p><p>上述命令使用 <code>vi</code> 编辑器打开了指定的目录，其中目录内的文件都会对应一个数字。下面你可以按照 <code>vi</code> 的操作方式来编辑目录中的这些文件：例如，删除行意味着删除目录中对应的文件，修改行中字符串意味着对文件进行重命名。</p><p>你也可以编辑子目录。下面的命令会编辑当前目录及所有子目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find | vidir -</span></span></code></pre></div><p>请注意命令结尾的 <code>-</code>。如果 <code>-</code> 被指定为待编辑的目录，<code>vidir</code> 会从标准输入读取一系列文件名，列出它们让你进行编辑。</p><p>如果你只想编辑当前目录下的文件，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -type f | vidir -</span></span></code></pre></div><p>只想编辑特定类型的文件，例如 <code>.PNG</code> 文件？你可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vidir *.png</span></span></code></pre></div><p>这时命令只会编辑当前目录下以 <code>.PNG</code> 为后缀的文件。</p><h4 id="vipe-实用程序" tabindex="-1">vipe 实用程序 <a class="header-anchor" href="#vipe-实用程序" aria-label="Permalink to “vipe 实用程序”">​</a></h4><p><code>vipe</code> 命令可以让你使用默认编辑器接收 Unix 管道输入，编辑之后使用管道输出供下一个程序使用。</p><p>执行下面的命令会打开 <code>vi</code> 编辑器（当然是我默认使用的编辑器），你可以编辑 <code>echo</code> 命令的管道输入（即 “Welcome to OSTechNix”），最后将编辑过的内容输出到终端中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Welcome to OSTechNIx&quot; | vipe</span></span>
<span class="line"><span>Hello World</span></span></code></pre></div><p>从上面的输出可以看出，我通过管道将 “Welcome to OSTechNix” 输入到 <code>vi</code> 编辑器中，将内容编辑为 “Hello World”，最后显示该内容。</p><p>好了，就介绍这么多吧。我只介绍了一小部分实用程序，而 <code>moreutils</code> 包含更多有用的实用程序。我在文章开始的时候已经列出目前 <code>moreutils</code> 软件包内包含的实用程序，你可以通过 <code>man</code> 帮助页面获取更多相关命令的细节信息。举个例子，如果你想了解 <code>vidir</code> 命令，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man vidir</span></span></code></pre></div><p>希望这些内容对你有所帮助。我还将继续分享其它有趣且实用的指南，如果你认为这些内容对你有所帮助，请分享到社交网络或专业圈子，也欢迎你支持 OSTechNix 项目。</p><p>干杯！</p><hr>`,89)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.ostechnix.com/moreutils-collection-useful-unix-utilities/"},{default:n(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/moreutils-collection-useful-unix-utilities/",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=e("作者：",-1)),a(i,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(i,{href:"https://github.com/pinewall"},{default:n(()=>[...s[4]||(s[4]=[e("pinewall",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const v=t(r,[["render",h]]);export{y as __pageData,v as default};
